grid = np.array([[int(x) for x in line.split(',')] for line in data.strip().split('\n')])
print("done")

def conway_step(grid):
    n = grid.shape[0]
    new_grid = np.zeros_like(grid)
    for i in range(n):
        for j in range(n):
            # Count live neighbors (8 directions)
            neighbors = 0
            for di in [-1, 0, 1]:
                for dj in [-1, 0, 1]:
                    if di == 0 and dj == 0:
                        continue
                    ni, nj = (i + di) % n, (j + dj) % n
                    neighbors += grid[ni, nj]

            # Conway's rules
            if grid[i, j] == 1:
                new_grid[i, j] = 1 if neighbors in [2, 3] else 0
            else:
                new_grid[i, j] = 1 if neighbors == 3 else 0
    return new_grid

